/* UI Contract only. All apparent commands are synthetic, task-local, in memory. */
'use strict';
(() => {
  const M=globalThis.ContractModel,root=document.querySelector('#app'),modal=document.querySelector('#modal');
  let tasks=M.create(),active=null,mode='quick',view='chat',artifact='overview',stage='new',inspector=false,inspectTab='evidence',sidebar=false,entry='direct',notice='',reverse=false,lastFocus=null,homeDraft='';
  const selected={sales:new Set(),member:new Set()},messageDraft={sales:'',member:''},readPositions={};
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const t=()=>tasks[active],money=n=>n.toLocaleString('zh-CN'),b=(action,label,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
  const stages=[['new','新建分析'],['prepare','数据准备'],['process','本地处理'],['analysis','循证分析'],['report','报告'],['feedback','执行反馈']];
  const statusNames={saved:'已保存 · 合成结果',waiting:'等待需求确认',running:'正在分析 · 合成事件',partial:'部分结果 · 尚有缺口',stopping:'正在停止 · 尚未结束',stopped:'已停止 · 结果保留',unknown:'请求结果未知 · 先读回',failed:'请求失败 · 草稿保留'};
  const sourceLabel=origin=>({'MODEL':'MODEL生成原文','USER':'USER手动编辑','MODEL_SUGGESTION_USER_APPLIED':'MODEL建议 · 用户采用'}[origin]||'历史来源未确认')+' · 未经新增事实核验';
  function announce(s){notice=s;document.querySelector('#announcement').textContent=s;}
  function showModal(title,html){lastFocus=document.activeElement;document.querySelector('#modal-body').innerHTML=`<h2 id="modal-title">${esc(title)}</h2>${html}`;modal.showModal();}
  modal.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
  function selectTask(id){active=id;sidebar=false;notice='同一任务草稿与引用保留；没有后台请求';}
  function nav(){return `<aside class="sidebar${sidebar?' open':''}" aria-label="项目与任务"><div><div class="brand">Juaner<span>AI</span></div><div class="slogan">持续做出更好的决策</div></div>${b('home','＋ 新建分析','new primary')}${sidebar?b('sidebar-close','关闭导航','quiet mobilemenu'):''}<div class="navgroup"><div class="meta">工作空间</div>${b('projects','▱ 项目与任务','navitem')}${b('materials','▤ 本地资料','navitem')}${b('assets','◇ 项目口径','navitem')}</div><div class="navgroup"><div class="meta">最近任务</div>${Object.values(tasks).map(x=>b('task',`${esc(x.title)}<span class="meta">${esc(x.project)} · ${x.id==='sales'?'已保存':'需求草稿'}</span>`,'navitem'+(active===x.id?' active':''),`data-id="${x.id}"`)).join('')}</div><div class="bottom"><div class="meta">Personal · 本机工作空间</div>${b('capabilities','更多能力与设置','navitem')}<div class="meta">合成审核 · 不连接产品服务</div></div></aside>`;}
  function home(){return `<main id="main" class="home" tabindex="-1"><h1>今天，要做出什么更好的决策？</h1><p class="intro">从一个真实问题开始，把数据变成有依据的判断。</p><div class="entry" aria-label="开始方式">${[['direct','直接开始分析'],['clarify','先帮我理清需求'],['manual','自己写下需求']].map(([id,label])=>b('entry',label,entry===id?'active':'',`data-id="${id}" aria-pressed="${entry===id}"`)).join('')}</div><div class="inputbox"><label class="sr" for="home-question">希望解决的业务问题</label><textarea id="home-question" placeholder="例如：9月销售下降了，我应该先看哪里？"></textarea><footer>${b('upload','＋ 添加资料','quiet')}<div>${b('framework','查看完整方案')}${b('start-demo','进入合成样例 →','primary')}</div></footer></div><p class="meta">${entry==='clarify'?'先整理目标、范围、方法与需要的证据；保存和确认不会自动执行。':entry==='manual'?'你可以直接写下需求，未知项保持待补，不由产品替你发明。':'已有明确问题可直接进入；必要澄清与授权仍会保留。'} 本审核稿不会读取你的文件。</p><div class="startergrid">${b('sample-sales','<strong>先定位经营变化</strong><span class="meta">销售下降集中在哪里？哪些判断还缺证据？</span>','starter')}${b('sample-member','<strong>先把需求想清楚</strong><span class="meta">会员复购如何定义？希望做出什么决定？</span>','starter')}</div><div class="auditnotes"><p class="meta">审核范围：浏览器工作台；整体参照附件浅色布局，专业六阶段和已有能力不删减。</p><a href="../proposal-v0.1.md">完整方案</a> · <a href="../ui-contract-v0.1.md">文字 UI Contract</a> · <a href="../baseline-and-coverage.md">能力保留对照</a></div></main>`;}
  function citations(x){return x.citations.map((c,i)=>`<div class="citation${M.staleCitation(x,c)?' stale':''}"><strong>${c.kind==='rows'?'数据行引用':'文本段引用'} · ${M.staleCitation(x,c)?'已过期，不可发送':'待发送'}</strong><div>${esc(c.label)}</div><div class="meta">${esc(x.project)} / ${esc(x.title)} · 分析r${c.analysis}${c.kind==='text'?` / 内容v${c.v} / ${c.part==='facts'?'事实段':'解释段'}`:` / ${esc(c.snapshot)} / ${c.ids.join('、')}`}</div><div class="actionrow">${b('locate-citation','定位来源','small',`data-index="${i}"`)}${b('remove-citation','移除','small',`data-index="${i}"`)}</div></div>`).join('');}
  function composer(x,compact=false){const block=x.readonly||x.status==='unknown'||x.citations.some(c=>M.staleCitation(x,c));return `<section class="composer" aria-label="${compact?'同任务成果助手':'同任务追问'}">${compact?'<h3>同任务助手</h3><p class="meta">与对话页共用草稿与引用，不创建第二会话。</p>':''}${citations(x)}<label class="sr" for="message">本任务追问</label><textarea id="message" placeholder="引用一个发现，继续追问，或调整这段报告表达……">${esc(messageDraft[x.id])}</textarea><footer><div><span class="meta">合成消息 · 无模型／后台请求</span><br>${b('upload','＋ 资料','quiet small')}${b('capabilities','更多能力','quiet small')}</div>${b('send','发送','primary',block?'disabled title="只读、UNKNOWN或过期引用，请先处理"':'')}</footer></section>`;}
  function metrics(){return `<div class="metricgrid"><div class="metric"><span class="meta">8月净销售额 · 元</span><strong>1,280,000</strong></div><div class="metric"><span class="meta">9月净销售额 · 元</span><strong>1,126,400</strong></div><div class="metric"><span class="meta">环比变化 · 已核验合成值</span><strong>−12.0%</strong></div></div>`;}
  function findings(){return `<div class="finding"><h3>下降主要集中在两家门店</h3><p>虹桥与徐汇合计下降123,600元，占总降幅的80.5%。这说明分布集中，不代表已找到原因。</p>${b('evidence','查看 80.5% 的依据 ↗','quiet small')}</div><div class="finding"><h3>老会员维度也值得单独复核</h3><p>老会员销售下降占总降幅97.7%。它与门店维度重叠，不能相加，也不能替代复购率。</p>${b('add-finding','将已核验发现纳入报告','small')}</div>`;}
  function chat(x){if(!x.ready)return `<div class="section"><div class="question">我想了解会员复购表现，但还没确定复购的口径。</div><div class="assistant-label">JuanerAI · 需求整理</div><h2>先把希望得到的答案想清楚</h2><p>分析对象、周期、复购定义和资料范围需要明确；我们不替你发明默认值。</p><div class="card"><h3>我们准备这样分析</h3><p>核对项目已批准的会员指标版本，区分交易次数、复购人数与老会员销售。</p><span class="status warning">方案草稿 · 尚未执行</span><div class="actionrow">${b('framework','查看完整方案')}${b('confirm-plan',x.planConfirmed?'方案已确认':'确认方案','',x.planConfirmed?'disabled':'')}${b('synthetic-run','开始合成分析','primary',x.planConfirmed?'':'disabled')}</div></div>${composer(x)}</div>`;return `<div class="question">9月销售比8月下降，帮我看看应该先排查什么。<div class="meta">本合成样例 · 同一任务上下文</div></div><div class="assistant-label">JuanerAI · 基于合成资料</div><h2>先看下降集中在哪里，再决定下一步。</h2><p>已按本例净销售额口径复核变化；当前证据支持定位分布，尚不能证明客流、价格或复购是原因。</p>${metrics()}${findings()}<div class="card"><strong>下一步需要你的判断</strong><p class="meta">是否优先补充两家门店的客流与成交结构？这不是自动执行的经营动作。</p><div class="actionrow">${b('report','打开报告编审','primary')}${b('framework','查看本次方案')}${b('collaboration','查看协作来源')}</div></div>${x.messages.map(m=>`<div class="question"><div class="meta">合成追问 · ${m.citations.length}个引用</div>${esc(m.text)}</div>`).join('')}${composer(x)}`;}
  function data(x){if(!x.ready||x.id!=='sales')return '<section class="empty"><h2>尚无数据结果</h2><p>当前任务尚未执行，资料与口径待补；不可引用其他任务的结果。</p></section>';const rs=reverse?[...M.rows].reverse():M.rows;return `<h2>数据结果</h2><p class="meta">合成已核验结果 · 分析r${x.analysis} · ${esc(x.snapshot)}。下表为4行结果，不是原始明细全量。</p><div class="actionrow">${b('cite-rows',`引用已选 ${selected[x.id].size} 行`,'primary')}${b('sort',reverse?'恢复门店顺序':'倒序查看')}${b('source-update','合成：更新来源版本','small')}</div><div class="tablewrap" role="region" aria-label="可引用门店结果表" tabindex="0"><table><thead><tr><th scope="col">选择</th><th scope="col">门店 / 稳定行ID</th><th scope="col">8月净销售额</th><th scope="col">9月净销售额</th><th scope="col">变化 · 元</th></tr></thead><tbody>${rs.map(r=>`<tr><td><input type="checkbox" data-row="${r.id}" aria-label="选择${r.name} ${r.id}" ${selected[x.id].has(r.id)?'checked':''}></td><th scope="row">${r.name} <span class="meta">${r.id}</span></th><td>${money(r.before)}</td><td>${money(r.after)}</td><td>−${money(r.before-r.after)}</td></tr>`).join('')}</tbody></table></div><div class="actionrow">${b('materials','查看原资料与预览限制','quiet small')}${b('no-row-id','无稳定身份时如何处理','quiet small')}</div><p class="meta">已选ID：${[...selected[x.id]].join('、')||'无'}。排序不会改变引用指向。选中不代表允许发送到模型。</p>`;}
  function report(x){if(!x.ready)return `<div class="empty"><h2>尚无报告</h2><p>先确认需求与方案，再显式开始适用分析。审核稿不会将预演变成结果。</p>${b('framework','回看需求与方案')}</div>`;
    const c=M.currentConfirmation(x),block=M.confirmBlock(x),stale=M.staleSuggestion(x);
    return `<article class="report"><header><span class="factlabel">单一当前主稿 · 合成审核</span><h2>9月销售变化分析</h2><p class="meta">内容 v${x.doc.v} · 分析 r${x.analysis} · 4店 / 2026年8–9月 · ${esc(x.snapshot)}</p></header><section class="facts"><div class="factlabel">计算事实 · 只读</div><p data-part="facts">9月净销售额1,126,400元，较8月1,280,000元下降12.0%。虹桥与徐汇合计下降123,600元，占总降幅80.5%。</p><p class="meta">退款归属：本合成例按原订单支付月；不作为产品默认指标定义。</p>${x.doc.extra?'<p>已纳入发现：老会员销售下降150,000元，占总降幅97.7%，与门店分解重叠，不能相加。</p>':''}<div class="actionrow">${b('quote-facts','引用事实段','small')}${b('revise-analysis','需要调整数字或口径？','quiet small')}</div></section><section class="section subtleline"><h3>解释与建议 <span class="meta">用户可编审表达</span></h3><p data-part="interpretation">${esc(x.doc.text)}</p><div class="actionrow">${b('quote-selection','引用选中文本','small')}${b('quote-paragraph','引用此段','small')}${b('generate','生成合成改写建议','small')}${b('edit-focus','手动编辑','quiet small')}</div><label class="meta" for="report-editor">编辑解释段（不修改计算事实）</label><textarea class="editor" id="report-editor" ${x.readonly?'readonly':''}>${esc(x.draft)}</textarea><div class="dirtyFlag">${M.dirty(x)?'未保存 · 当前显示的编辑不是已保存报告':'当前编辑与保存版一致'}</div><div class="actionrow">${b('save','保存这段表达','primary',x.readonly||x.status==='unknown'?'disabled':'')}${b('discard-edit','放弃未保存编辑')}${b('save-failure','合成：下一次保存失败','quiet small')}${b('save-unknown','合成：保存结果未知','quiet small')}</div>${x.error?`<p class="warning notice">${esc(x.error)}</p>`:''}</section>${x.pending?`<section class="card" aria-label="改写建议对照"><h3>${stale?'建议已过期 · 未应用':'待审建议 · 未修改主稿'}</h3><p class="meta">基于分析r${x.pending.analysis} / 内容v${x.pending.v}；只改这段表达，不改变事实。</p><div class="compare"><div><strong>发起时原文</strong><p>${esc(x.pending.base)}</p></div><div><strong>固定合成建议</strong><p>${esc(x.pending.text)}</p></div></div><div class="actionrow">${b('apply','应用到这版报告','primary',stale||x.readonly||x.status==='unknown'?'disabled':'')}${b('discard-suggestion','放弃建议')}${b('external-save','合成：另一端已保存新版','small')}</div></section>`:''}<section class="subtleline"><h3>核验情况与必要限制 · 不可删除</h3><p>本例仅定位描述性变化；未核验客流、单价、复购定义或因果关系。合成算术一致不证明真实模型质量、业务判断或经营效果。</p></section><section class="confirmation"><h3>${c?`报告内容 v${c.v} 已确认${c.partial?'（仅部分结果与限制）':''}`:'当前报告内容尚未确认'}</h3><p class="meta">既有分析认可：分析r1的历史记录；不代表已确认本版报告表达。</p>${block?`<p class="meta">暂不可确认：${esc(block)}</p>`:''}<div class="actionrow">${b('confirm',x.status==='partial'?'确认这版部分结果与限制':'确认这版报告内容','primary',block||c?'disabled':'')}${b('download','下载合成摘要')}${b('formal','查看正式评审边界','quiet small')}</div><p class="meta">报告确认不批准业务决定，不执行现实行动。</p></section><details class="history"><summary>版本与确认历史（${x.history.length}个旧稿，${x.confirmations.length}条确认）</summary>${x.confirmations.map(v=>`<p>内容v${v.v} / 分析r${v.analysis} ${v.invalid?`历史确认 · 不再适用：${esc(v.invalid)}`:'已确认该精确版本'}${v.partial?' · 仅部分结果与限制':''}</p>`).join('')}${x.history.map(h=>`<p>历史稿内容v${h.v} / 分析r${h.analysis}：${esc(h.text)}</p>`).join('')||'<p>没有旧稿；不会编造历史。</p>'}</details></article>`;}
  function overview(){return `<h2>本次分析成果</h2><p class="meta">合成样例 · 描述性变化，不是因果证明</p>${metrics()}<div class="barplot" aria-label="四店销售下降金额">${M.rows.map((r,i)=>`<div class="barrow"><span>${r.name}</span><div class="bar"><i class="${['w100','w65','w28','w12'][i]}"></i></div><span>−${money(r.before-r.after)}</span></div>`).join('')}</div>${findings()}`;}
  function artifactBody(x){return `<div class="artifactbar"><div class="segmented" aria-label="成果分类">${[['overview','概览'],['data','数据结果'],['report','报告编审']].map(([id,l])=>b('artifact',l,artifact===id?'active':'',`data-id="${id}" aria-pressed="${artifact===id}"`)).join('')}</div><span class="meta">分析r${x.analysis} / 内容v${x.doc.v}</span></div><div class="${inspector?'artifact-body':'split-artifact'}"><div>${artifact==='report'?report(x):artifact==='data'?data(x):x.ready?overview():'<div class="empty">尚未执行分析，没有结果。</div>'}</div><aside class="mini-assistant">${composer(x,true)}</aside></div>`;}
  function evidence(){const current=t();if(!current?.ready||current.id!=='sales')return '<section class="empty"><h2>尚无已保存依据</h2><p>本任务尚未执行，没有计算、核验或报告；销售任务的依据不会带入。</p></section>';return `<h2>依据目录</h2><p>计算值、核验结果、假设与人的判断分别查看。</p><div class="card"><h3>E01 · 净销售额变化</h3><p>(1,126,400 − 1,280,000) ÷ 1,280,000 = −12.0%。</p><p class="meta">合成计算样例；来源、口径、分析版本真实产品需绑定实际证据。</p>${b('materials','查看资料与范围')}</div><div class="card"><h3>E02 · 两店降幅贡献</h3><p>(75,000 + 48,600) ÷ 153,600 = 80.5%。仅门店分布，不证明客流原因。</p>${b('data','定位门店结果行')}</div><div class="card"><h3>H01 · 是否由老会员复购引起？</h3><span class="status warning">尚无该因果判断</span><p>老会员销售≠复购率；需要独立定义与适用证据。不得用数值核验冒充结论支持。</p></div><div class="actionrow">${b('collaboration','协作意见与来源')}${b('assets','口径版本与适用性')}${b('process','过程与独立核验')}</div>`;}
  function professional(x){if(!x.ready&&stage==='prepare')return '<h2>2 · 数据准备</h2><div class="empty"><p>当前会员任务资料与指标版本待补，尚无结果或可引用行。</p></div>'+b('materials','查看资料规则')+b('assets','查看口径规则')+composer(x);switch(stage){case'new':return `<h2>1 · 新建分析</h2><p>明确业务问题，先整理需求和方法，不把预演当结果。</p>${frameworkHtml()}${composer(x)}`;case'prepare':return `<h2>2 · 数据准备</h2><div class="card"><h3>销售记录.csv · 合成</h3><p>4店、2026年8–9月；表格预览仅展示已可读范围，真实格式处理沿用原能力。</p><div class="actionrow">${b('materials','预览资料与限制')}${b('assets','检查项目口径')}${b('permission','查看资料与模型授权')}</div></div>${data(x)}${composer(x)}`;case'process':return `<h2>3 · 本地处理</h2><div class="card"><span class="status">${esc(statusNames[x.status])}</span><h3>适用计算 → 独立核验 → 结果保存</h3><p>本审核稿没有实际执行工具。生产面继续呈现实际IR、方法、调用／核验摘要和partial／unsupported。</p>${b('process','打开方案、IR与核验详情')}</div>${controls(x)}${composer(x)}`;case'analysis':return `<h2>4 · 循证分析</h2>${x.ready?evidence():'<p>尚无证据，不生成假结论。</p>'}${b('collaboration','打开Fork／Subagent协作树')}${composer(x)}`;case'report':return `<h2>5 · 报告</h2>${artifactBody(x)}`;default:return `<h2>6 · 执行反馈</h2><div class="card"><h3>分析、决定、行动与效果分别记录</h3><p>当前${x.id==='sales'?'合成销售样例不满足原会员方案正式评审条件':'会员任务仅为需求草稿，尚未形成适用结果'}，没有真实行动或业务回执。</p><div class="actionrow">${b('formal','查看既有正式评审结构')}${b('outcome','查看后续观察边界')}</div></div><p class="meta">适用已有任务保留原正式决定与Owner／观察安排。不把Change007或完整Actual闭环当成当前已实现。</p>${composer(x)}`;}}
  function controls(x){return `<div class="card"><h3>异常与恢复 · 审核控制</h3><p class="meta">下面按钮只注入合成状态，不接触产品任务。刷新页面会重置本原型；产品要求真实持久化另验。</p><div class="actionrow">${[['running','运行'],['partial','部分结果'],['unknown','结果未知'],['failed','已知失败'],['stopping','停止中'],['stopped','已停止'],['saved','已保存']].map(([id,label])=>b('status',label,'small',`data-id="${id}"`)).join('')}</div><div class="actionrow">${b('readback','先读回保存状态')}${b('stop','请求停止')}${b('stop-complete','合成：收到已停止回执')}${b('readonly',x.readonly?'解除合成只读':'模拟只读')}</div><p class="meta">当前：${esc(statusNames[x.status])}${x.readonly?' · 只读':''}；不自动重试、续跑、抢占或重置授权额度。</p></div>`;}
  function inspectorHtml(x){if(!x.ready||x.id!=='sales')return '<aside class="inspector" aria-label="当前任务检查器">'+b('inspector-close','关闭','quiet small closepanel')+'<h3>当前任务待准备</h3><p>会员需求尚未确认／执行；没有销售结果、证据或可引用报告。</p>'+b('framework','查看本任务方案')+b('permission','查看权限规则')+'</aside>';return `<aside class="inspector" aria-label="当前任务检查器">${b('inspector-close','关闭','quiet small closepanel')}<h3>检查详情</h3><div class="segmented" aria-label="检查器分类">${[['evidence','证据'],['context','口径与资产'],['process','过程']].map(([id,l])=>b('inspect-tab',l,inspectTab===id?'active':'',`data-id="${id}" aria-pressed="${inspectTab===id}"`)).join('')}</div>${inspectTab==='evidence'?`<div class="evidenceitem"><h3>E01 · 数值计算</h3><p>净销售额环比 −12.0%；合成算术已核对，不证明原因。</p>${b('evidence','展开逐数字依据','quiet small')}</div><div class="evidenceitem"><h3>E02 · 门店分解</h3><p>虹桥、徐汇合计80.5%。来源按稳定ID定位。</p>${b('data','定位数据结果','quiet small')}</div><div class="evidenceitem"><h3>需要补充的证据</h3><p>客流／成交结构未知。老会员维度与门店分解不可相加。</p></div>`:inspectTab==='context'?`<div class="evidenceitem"><h3>本次口径与范围</h3><p>合成净销售额／4店／8–9月；快照独立，非产品默认规则。</p>${b('assets','查看项目口径与采用','quiet small')}</div><div class="evidenceitem"><h3>资料</h3><p>原始预览与结果行不同；前10行不代表全量。</p>${b('materials','查看资料','quiet small')}</div><div class="evidenceitem"><h3>分析方案</h3><p>方案确认≠执行授权；历史计划复用不复制旧结果。</p>${b('framework','查看方案／变化','quiet small')}</div>`:`<div class="evidenceitem"><h3>过程与核验</h3><p>实际计划／IR、计算、独立核验、保存状态，不展示隐藏思维链。</p>${b('process','展开过程','quiet small')}</div><div class="evidenceitem"><h3>协作</h3><p>独立对话、血缘、范围、意见回流／父使用／正式采纳分列。</p>${b('collaboration','查看协作树','quiet small')}</div><div class="evidenceitem"><h3>版本与请求</h3><p>分析r${x.analysis}／内容v${x.doc.v}；UNKNOWN先读回。</p>${b('exceptions','恢复与控制','quiet small')}</div>`}</aside>`;}
  function render(){const focusKey=document.activeElement?.dataset?.action;const x=t();root.innerHTML=`<div class="reviewbar"><strong>UI Contract v0.1 · 合成审核</strong><span class="reviewhint">无模型／真实计算／业务保存 · 待用户批准 · 不进入开发</span>${[['home','首页'],['scene-chat','对话与证据'],['scene-data','数据选区'],['scene-report','报告编审'],['scene-confirm','确认失效'],['scene-pro','专业六阶段'],['exceptions','异常恢复'],['reset','重置样例']].map(([a,l])=>b(a,l)).join('')}</div><div class="shell">${nav()}<div class="workspace"><header class="topbar">${b('sidebar','☰','quiet mobilemenu','aria-label="打开项目导航"')}<div class="crumb">${x?esc(x.project)+' / '+esc(x.title):'Personal 工作空间 / 新建分析'}</div><div class="top-actions"><div class="segmented" aria-label="工作模式">${b('mode','简洁',''+(mode==='quick'?'active':''),'data-id="quick" aria-pressed="'+(mode==='quick')+'"')}${b('mode','专业',''+(mode==='pro'?'active':''),'data-id="pro" aria-pressed="'+(mode==='pro')+'"')}</div>${x?b('inspector','检查详情','small'):b('about','审核说明','quiet small')}</div></header>${!x?home():`<header class="taskhead"><div><h1>${esc(x.title)}</h1><p class="meta">${esc(x.project)} · ${x.ready?'4店 / 8–9月 · ':''}分析 r${x.analysis} · ${esc(x.snapshot)}</p></div><span class="status${['unknown','partial','stopping','failed'].includes(x.status)?' warning':''}">${esc(statusNames[x.status])}${x.readonly?' / 只读':''}</span></header>${notice?`<div class="notice" role="status">${esc(notice)}</div>`:''}${mode==='pro'?`<nav class="stages" aria-label="专业六阶段">${stages.map(([id,l],i)=>b('stage',`${i+1} ${l}`,stage===id?'active':'',`data-id="${id}" aria-current="${stage===id?'step':'false'}"`)).join('')}</nav>`:`<nav class="viewtabs" aria-label="任务视图">${[['chat','对话'],['artifacts','成果'],['evidence','依据']].map(([id,l])=>b('view',l,view===id?'active':'',`data-id="${id}" aria-pressed="${view===id}"`)).join('')}</nav>`}<div class="content${inspector?' inspected':''}"><main id="main" class="primary-pane" tabindex="-1">${mode==='pro'?professional(x):view==='artifacts'?artifactBody(x):view==='evidence'?evidence():chat(x)}</main>${inspector?inspectorHtml(x):''}</div>`}</div></div>`;
    if(!x){const homeInput=root.querySelector('#home-question');if(homeInput)homeInput.value=homeDraft;}
    if(x&&!x.ready){const meta=root.querySelector('.artifactbar>.meta');if(meta)meta.textContent='尚未执行 · 无报告内容版本';}
    const reportElement=root.querySelector('.report');
    if(x&&reportElement){const origin=document.createElement('p');origin.className='meta';origin.dataset.origin=x.doc.origin;origin.textContent=sourceLabel(x.doc.origin);reportElement.querySelector('[data-part="interpretation"]')?.before(origin);const lines=reportElement.querySelectorAll('.history p');x.history.forEach((h,i)=>lines[x.confirmations.length+i]?.prepend(document.createTextNode(sourceLabel(h.origin)+' · ')));if(x.conflict){const conflict=document.createElement('section');conflict.className='card warning';conflict.setAttribute('aria-label','保存版本冲突');conflict.innerHTML=`<h3>另一端已更新 · 本地未保存稿仍在</h3><div class="compare"><div><strong>本地未保存稿</strong><p>${esc(x.conflict.localDraft)}</p></div><div><strong>当前保存稿 v${x.conflict.serverV}</strong><p>${esc(x.conflict.serverText)}</p></div></div><p class="meta">没有强行覆盖。选择保留草稿用于基于新版重新编辑，或放弃草稿回到保存稿。</p><div class="actionrow">${b('conflict-keep','保留草稿，基于新版重新编辑','primary')}${b('conflict-discard','放弃本地草稿')}</div>`;reportElement.querySelector('#report-editor')?.before(conflict);}}
    if(focusKey){const match=[...root.querySelectorAll('button')].find(el=>el.dataset.action===focusKey&&!el.disabled);match?.focus({preventScroll:true});}
    const overlay=window.innerWidth<1024&&sidebar?root.querySelector('.sidebar.open'):window.innerWidth<1280&&inspector?root.querySelector('.inspector'):null;
    if(overlay){overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');const main=root.querySelector('#main');if(main)main.inert=true;overlay.querySelector('button')?.focus({preventScroll:true});}
  }
  function frameworkHtml(){return `<div class="card"><h3>我们准备这样分析</h3><dl><dt>业务目标</dt><dd>先定位变化分布，区分事实、解释和下一步判断。</dd><dt>范围与资料</dt><dd>本次已选择资料及版本；未知内容保持待补。</dd><dt>方法与证据</dt><dd>先核对口径及适用性，再计算、独立核验；不足项明确说明。</dd></dl><details><summary>方案变更对照（合成历史）</summary><p>原：所有门店 → 当前：4家有可比数据的门店。旧结果仍可查看，受影响结果需要重新计算；授权不自动扩大。</p></details><details><summary>预演不同答案（不是事实）</summary><p>可能支持／可能反证／证据不足只用于需求讨论，必须补实际资料与核验。</p></details><div class="actionrow">${b('save-plan','保存，稍后继续')}${b('confirm-plan','确认方案')}${b('synthetic-run','开始合成分析','primary',t()?.planConfirmed?'':'disabled')}</div><p class="meta">这些操作只改变审核样例；真实方案／权限／执行仍按现有合同分别处理。</p></div>`;}
  const modalContent={
    materials:['资料与预览范围','<p>合成 sales.csv，4店×2期。当前表格是结果行，不是原始资料。</p><p>生产保留原格式支持／错误与前10行预览，全量与预览分开。原始资料无稳定行身份时不可引用；未授权资料不会因选中而入模。</p>'],
    assets:['项目口径与资产','<p>项目候选 → 审阅批准 → 未来任务默认；当前任务是否采用另记。</p><p>本例退款归属按原订单支付月，只是合成例，不覆盖006已批准的会员指标版本。修改默认不会追写当前任务；版本不兼容／零分母分别显示不支持／不适用，不能猜成0。</p><p>生产保留导入／注册／适用性检查／当前任务显式采用。此处不写真实资产。</p>'],
    collaboration:['协作树与独立边界','<p>主任务 → Fork：门店变化比较 → Subagent：指标复核（合成血缘）。各自独立对话、已授权材料范围、运行／停止状态。</p><p>子意见已返回 ≠ 父模型已使用 ≠ 数字已核验 ≠ 正式采纳。原已批准范围内可自动回流，不新增每次人工批准。手动正式采纳保留原记录。</p><p>本期只重排已有协作能力，不开启通用Agent平台或新权限。</p>'],
    process:['处理方案、IR与独立核验','<p>合成流程：理解范围 → 适用IR → 本地描述性计算 → 适用方法独立核验 → 保存结果。</p><p>生产保留实际方法选择、工具事件、部分成功／未核验／unsupported、资源与停止摘要；不展示隐藏思维链。</p><p>本稿未调用计算工具／Provider；不以固定进度动画或这段说明替代工程证据。</p>'],
    formal:['正式评审与报告确认不同','<p>原适用会员方案的正式评审保留：analysis / more_evidence / choice；no_action / defer / candidate，Owner、baseline、expected observation、window、guardrail及风险。</p><p>只有实际满足既有方案版本／结果条件才可提交。当前合成销售任务不满足，不能提交。确认报告内容不会创建正式决定；正式决定不会执行现实行动。</p><p>本稿不实现Change007，不迁移或自动重批历史决定。</p>'],
    outcome:['后续观察与效果','<p>当前没有现实行动／Actual／经营效果。已有观察安排可读；未来结果、复盘与下一Case采用遵循独立批准能力，不能从“报告已确认”推出。</p>'],
    permission:['资料与模型权限','<p>保留原材料作用域、明细读取边界与累计资源授权。选中／引用仅是待发送上下文，不增加权限。</p><p>发送前重新校验；权限变更则引用不可用，不能回显受限正文或沿用旧授权。新范围须用户明确决定。本原型无真实数据、凭据或Provider。</p>'],
    capabilities:['更多能力与设置','<p>保留：Skill／提示模板、方案复用、Fork／Subagent、已有安全配置与布局设置、任务搜索和项目入口。</p><p>方案复用创建独立任务，不复制结果／授权。账号与未接入插件明确“未接入”，不显示虚假的可用状态；不扩展新平台。</p><p>布局设置不会使内容确认失效。真实凭据保持现有安全入口，不在审核稿输入或展示。</p>'],
    'no-row-id':['无稳定身份，不伪造引用','<p>此处展示前10行原始预览的能力边界：若后端没有可验证的来源／行身份，“引用这些行”应禁用并解释原因。</p><p>不能以DOM行号、排序位置或截图里的数字冒充稳定引用。本稿结果表使用合成S01–S04身份。</p>'],
    'revise-analysis':['事实变化回到分析修订','<p>数字、口径、范围或证据不是可润色文本。请回到方案变更对照，保留旧结果，明确受影响部分后按现有授权重新分析／核验。</p><p>报告改写不能直接篡改计算事实；旧确认与正式决定只保留历史，不自动沿用新版。</p>'],
    projects:['项目与任务','<p>当前两个合成任务各有独立草稿和引用。可从左侧切换检查，不把资料／授权／报告跨项目带过去。</p>'],
    about:['审核说明','<p>用户待审稿，不是已获批准的产品。所有操作仅在本页内存；刷新重置。无网络、模型、真实计算、真实上传或持久业务写入。</p><p>审核重点：整体布局、专业六阶段、选区与过期、单稿改写、确认失效和异常回退。文字Contract是未模拟复杂入口的完整语义来源。</p>']
  };
  root.addEventListener('input',e=>{if(e.target.id==='home-question'){homeDraft=e.target.value;return;}const x=t();if(!x)return;if(e.target.id==='report-editor'){x.draft=e.target.value;const suggestionHeading=root.querySelector('[aria-label="改写建议对照"] h3');if(suggestionHeading)suggestionHeading.textContent=M.staleSuggestion(x)?'建议已过期 · 未应用':'待审建议 · 未修改主稿';const flag=root.querySelector('.dirtyFlag');if(flag)flag.textContent=M.dirty(x)?'未保存 · 新编辑尚未确认':'当前编辑与保存版一致';const confirmBtn=root.querySelector('[data-action="confirm"]');if(confirmBtn)confirmBtn.disabled=!!M.confirmBlock(x)||!!M.currentConfirmation(x);const applyBtn=root.querySelector('[data-action="apply"]');if(applyBtn)applyBtn.disabled=M.staleSuggestion(x)||x.readonly||x.status==='unknown';}if(e.target.id==='message')messageDraft[x.id]=e.target.value;});
  const positionKey=()=>`${active||'home'}:${mode}:${mode==='pro'?stage:view}:${artifact}`;
  root.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const navigation=['task','home','mode','view','stage','artifact','data','report','evidence','sample-sales','sample-member'];if(navigation.includes(action)||action.startsWith('scene-')){readPositions[positionKey()]=window.scrollY;requestAnimationFrame(()=>window.scrollTo(0,readPositions[positionKey()]||0));}},true);
  root.addEventListener('change',e=>{if(e.target.dataset.row){const id=e.target.dataset.row;e.target.checked?selected[active].add(id):selected[active].delete(id);render();}});
  root.addEventListener('click',e=>{
    const el=e.target.closest('button[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;let x=t(),result='';
    if(action.startsWith('scene-')){selectTask('sales');x=t();mode=action==='scene-pro'?'pro':'quick';stage=action==='scene-pro'?'new':'report';inspector=action==='scene-chat';view=action==='scene-chat'?'chat':'artifacts';artifact=action==='scene-data'?'data':action==='scene-report'||action==='scene-confirm'?'report':'overview';if(action==='scene-confirm')notice='审核：先确认内容，再切页／模式应保持；保存不同表达后旧确认应失效。';render();return;}
    if(modalContent[action]){const [title,html]=modalContent[action];showModal(title,html);return;}
    switch(action){
      case'home':active=null;sidebar=false;break;
      case'reset':tasks=M.create();active=null;mode='quick';view='chat';artifact='overview';inspector=false;for(const key of Object.keys(selected)){selected[key].clear();messageDraft[key]='';}notice='';break;
      case'task':selectTask(id);break;
      case'entry':entry=id;break;
      case'start-demo':case'sample-sales':selectTask('sales');mode='quick';view='chat';break;
      case'sample-member':selectTask('member');mode='quick';view='chat';break;
      case'mode':mode=id;result='仅切换同任务展示模式；未创建任务／执行分析';break;
      case'view':view=id;break;
      case'stage':stage=id;break;
      case'artifact':artifact=id;break;
      case'data':view='artifacts';artifact='data';if(mode==='pro')stage='prepare';break;
      case'report':view='artifacts';artifact='report';if(mode==='pro')stage='report';break;
      case'evidence':view='evidence';if(mode==='pro')stage='analysis';inspector=true;inspectTab='evidence';break;
      case'inspector':inspector=!inspector;sidebar=false;break;
      case'inspector-close':inspector=false;break;
      case'inspect-tab':inspectTab=id;break;
      case'sidebar':sidebar=!sidebar;inspector=false;break;
      case'sidebar-close':sidebar=false;break;
      case'framework':showModal('完整分析方案 · 合成审核',frameworkHtml());return;
      case'upload':showModal('资料入口 · 不实际读取','<p>审核稿不弹真实文件选择、不读取文件内容。生产沿用已支持资料格式、范围／预览／权限及失败反馈；新增资料不自动进入模型或当前结果。</p>');return;
      case'confirm-plan':if(x){x.planConfirmed=true;result='合成方案已确认；尚未执行';}else result='先进入需求样例查看方案';break;
      case'save-plan':result='合成需求草稿保留；没有执行分析';break;
      case'synthetic-run':if(x?.planConfirmed){result='本页只演示：真实执行仍需适用资料、授权与后台，本稿未生成结果';}break;
      case'cite-rows':result=M.citeRows(x,[...selected[x.id]]);break;
      case'sort':reverse=!reverse;break;
      case'quote-facts':result=M.citeText(x,M.factText,'facts');break;
      case'quote-paragraph':result=M.citeText(x,x.doc.text);break;
      case'quote-selection':{const s=window.getSelection(),a=s?.anchorNode?.parentElement?.closest('[data-part]'),z=s?.focusNode?.parentElement?.closest('[data-part]');result=a&&a===z?M.citeText(x,s.toString(),a.dataset.part):'请在单一事实／解释段内选择；或使用“引用此段”';break;}
      case'locate-citation':{const c=x.citations[Number(el.dataset.index)];if(M.staleCitation(x,c)){result='该引用已过期，不能定位为当前来源；请回当前来源重新选择';}else{view='artifacts';artifact=c.kind==='rows'?'data':'report';if(mode==='pro')stage=c.kind==='rows'?'prepare':'report';}break;}
      case'remove-citation':x.citations.splice(Number(el.dataset.index),1);break;
      case'source-update':result=M.refreshSource(x);break;
      case'generate':result=M.generate(x);break;
      case'apply':result=M.apply(x);break;
      case'discard-suggestion':x.pending=null;result='建议已放弃，主稿未改';break;
      case'external-save':result=M.write(x,x.doc.text+' 先补充证据，再作业务判断。','合成另一端保存了表达',x.doc.extra,true);break;
      case'conflict-keep':x.conflict=null;result='本地草稿已保留，用于基于当前新版重新编辑；尚未保存，旧建议仍不可沿用';break;
      case'conflict-discard':x.draft=x.doc.text;x.conflict=null;result='已显式放弃本地草稿，回到当前保存稿；没有覆盖服务端版本';break;
      case'edit-focus':root.querySelector('#report-editor')?.focus();return;
      case'save':result=M.save(x);break;
      case'discard-edit':x.draft=x.doc.text;x.conflict=null;x.error=null;result='已放弃本任务未保存表达，保存版未变';break;
      case'save-failure':x.failNext=true;result='已设置合成失败：下次保存保留草稿且不写主稿';break;
      case'save-unknown':x.status='unknown';x.unknownSave=true;result='合成保存结果未知：先读回，不重复提交，草稿保留';break;
      case'confirm':result=M.confirm(x);break;
      case'add-finding':if(!x)break;if(M.dirty(x))result='先保存或放弃未保存表达，再纳入发现';else result=M.write(x,x.doc.text,'用户将已核验且适用的发现纳入报告',true);break;
      case'send':{const count=x.messages.length;result=M.send(x,messageDraft[x.id]);if(x.messages.length>count)messageDraft[x.id]='';break;}
      case'exceptions':if(!x){selectTask('sales');x=t();}showModal('异常恢复 · 合成控制',controls(x));return;
      case'status':x.status=id;result='已切换合成状态，不影响真实任务';break;
      case'readback':result=M.readback(x);break;
      case'stop':if(['running','unknown'].includes(x.status)){x.status='stopping';result='停止请求已接收，尚未确认执行结束';}else result='当前无已知在途合成执行；未停止任何产品进程';break;
      case'stop-complete':if(x.status==='stopping'){x.status='stopped';result='合成回执确认已停止；未自动恢复';}else result='必须先进入停止中，不能伪造已停回执';break;
      case'readonly':x.readonly=!x.readonly;result=x.readonly?'当前合成只读，不自动抢占控制权':'已解除合成只读；没有真实控制权变化';break;
      case'download':{const confirmed=M.currentConfirmation(x);const text=`【合成摘要 · 非完整版本副本 · 不是产品报告】\n来源：报告内容v${x.doc.v} / 分析r${x.analysis}\n来源报告状态：${confirmed?(confirmed.partial?'仅确认部分结果与限制':'这版合成内容已确认'):'未确认'}；本摘要不是确认对象。\n净销售额下降12.0%；两店贡献80.5%。${x.doc.extra?'\n已纳入发现：老会员销售下降占总降幅97.7%；与门店维度重叠，不可相加。':''}\n表达来源：${sourceLabel(x.doc.origin)}\n${x.doc.text}\n限制：合成算术不证明真实业务或原因。`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='JuanerAI-合成摘要-非完整副本.txt';a.click();URL.revokeObjectURL(url);result='仅下载合成摘要，非完整版本副本；不改变内容或确认，不是外部发布';break;}
    }
    if(result)announce(result);render();
  });
  // Dialog actions reuse the same handlers without claiming connected production forms.
  document.querySelector('#modal-body').addEventListener('click',e=>{const el=e.target.closest('button[data-action]');if(!el)return;const clone=el.cloneNode(true);clone.hidden=true;root.appendChild(clone);modal.close();clone.click();clone.remove();});
  document.addEventListener('keydown',e=>{if(modal.open)return;const overlay=root.querySelector('[aria-modal="true"]');if(!overlay)return;if(e.key==='Escape'){sidebar=false;inspector=false;render();root.querySelector('[data-action="inspector"]')?.focus();return;}if(e.key==='Tab'){const focusable=[...overlay.querySelectorAll('button:not(:disabled),a[href],input,textarea,[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
  render();
})();
